Object.assign(window.deepArticles,{
  "algol-latin":institutionArticle({
    slug:"algol-latin",title:"ALGOL-Latin",eyebrow:"Latin-bloc scientific language · 1962–1985",infoboxKicker:"Scientific and engineering language family",
    lead:"ALGOL-Latin is the shared scientific and engineering language family of the Latin Catholic bloc. Created as a practical regional extension of ALGOL 60, it lets Italian, Occitan, Iberian, and associated institutions exchange numerical programs without making any one national machine or natural language the bloc standard.",
    canon:"ALGOL-Latin 62 and 68, their major facilities, institutional uses, and relationship to ALGOL 60 are established. A complete revised report, exact lexical editions, and executable conformance suite remain open.",
    sections:[
      {id:"origin",title:"A neutral scientific language",html:"<p>Italian and Occitan laboratories adopt ALGOL 58 and ALGOL 60 because their international mathematical notation is less politically charged than choosing an Italian, French, Spanish, or Portuguese administrative language. The Latin institutions then standardize the missing practical services as a regional family.</p>"},
      {id:"algol60",title:"Inherited ALGOL 60 core",html:"<p>The portable core retains lexical block structure, typed declarations, procedures, recursion, dynamic activation stacks, and parameter passing by value or by name. Implementations must document numeric ranges and the representation of <code>own</code> variables rather than pretending that every machine behaves identically.</p>"},
      {id:"al62",title:"ALGOL-Latin 62",html:"<p>The 1962 edition adds standardized input and output, complex numbers, matrix operations, declared precision, error conditions, tape and file services, and separately compiled procedures. These additions turn a publication language into a usable tool for laboratories and engineering offices.</p>"},
      {id:"al68",title:"ALGOL-Latin 68",html:"<p>The 1968 edition adds records, modules, simulation packages, limited event and parallel facilities, and explicit linkage to assembly routines and devices. Hardware-facing and concurrent behavior is placed in named modules so the sequential scientific core remains intelligible.</p>"},
      {id:"simulation",title:"MODELO and MODÈLE packages",html:"<p>Standard simulation packages reproduce selected class, process, queue, and event ideas associated with Simula. Italian-language MODELO and Occitan/French MODÈLE documentation describe compatible facilities without requiring a German compiler or creating a separate language family.</p>"},
      {id:"institutions",title:"Universities and strategic industry",html:"<p>ALGOL-Latin is used in universities, nuclear engineering, navigation, aerospace, orbital calculation, civil construction, and advanced manufacturing. Administrative work normally belongs to <a href='lia-language.html'>LIA</a>, while control systems and logic research develop their own specialized languages.</p>"},
      {id:"portability",title:"Portability by declared profile",html:"<p>A conforming program names its edition, precision requirements, file profile, matrix library, and any device or parallel module. This discipline permits source exchange among unlike machines while acknowledging that numerical representation, peripherals, and operating services still differ.</p>"},
      {id:"position",title:"Position in 1985",html:"<p>By 1985 Pascal and <a href='modula-programming-language.html'>Modula</a> dominate much teaching and structured systems work, while C and national control languages expand. ALGOL-Latin nevertheless remains the bloc’s prestigious scientific common language and the archive form of many long-lived technical programs.</p>"}
    ],
    related:[{href:"latin-programming-languages.html",kicker:"Bloc overview",label:"Latin-bloc Programming Languages"},{href:"pascal-programming-language.html",kicker:"Teaching descendant",label:"Pascal"},{href:"modula-programming-language.html",kicker:"Modular descendant",label:"Modula"},{href:"lia-language.html",kicker:"Administrative counterpart",label:"LIA"},{href:"marseille-prolog.html",kicker:"Logic-programming tradition",label:"Marseille Prolog"}],
    primarySources:[{href:"https://archive.computerhistory.org/resources/text/algol/algol_bulletin/EX/RR60/INDEX.HTM",label:"Naur et al. — Revised Report on ALGOL 60"},{href:"https://archive.computerhistory.org/resources/text/algol/algol_bulletin/AS47/",label:"IFIP Working Group 2.1 — Revised Report on ALGOL 68"}],
    facts:[["First regional edition","ALGOL-Latin 62"],["Second major edition","ALGOL-Latin 68"],["Base language","ALGOL 60"],["Scope","Lexical blocks"],["Procedure parameters","Call by value or name"],["Strategic fields","Aerospace, nuclear power, navigation"],["Administrative counterpart","LIA"],["1985 status","Latin scientific common language"]]
  }),

  "modula-programming-language":institutionArticle({
    slug:"modula-programming-language",title:"Modula",eyebrow:"Modular systems-language family · 1973–1985",infoboxKicker:"Pascal-family systems language",
    lead:"Modula is Niklaus Wirth’s family of languages for modular, concurrent, and systems programming. Its explicit interfaces and separately compiled modules make it especially attractive to Latin-bloc and Commonwealth engineers who need larger systems than classroom Pascal can comfortably organize.",
    canon:"The historical Modula and Modula-2 lineage, modular design principles, and substantial Latin and Commonwealth engineering use are established. The exact editions selected by individual Latin institutions remain to be pinned.",
    sections:[
      {id:"first",title:"The first Modula",html:"<p>Wirth begins the original Modula project in 1973 to study concurrent processes and their synchronization on small computers. The language joins a minimal Pascal-like base to process construction and communication, and is used in the Hexapus laboratory network.</p>"},
      {id:"modula2",title:"Modula-2",html:"<p>The later Modula-2 revision turns modules into the central unit of program construction. Definition modules publish interfaces; implementation modules hide representation and algorithms; explicit imports state dependencies; and separate compilation preserves type checking across boundaries.</p>"},
      {id:"types",title:"Types and abstract data",html:"<p>Records, pointers, enumerations, sets, procedure types, open-array parameters, and opaque exported types support structured data and information hiding. A client can manipulate an abstract object through exported procedures without depending on its private record layout.</p>"},
      {id:"systems",title:"Systems and low-level access",html:"<p>Modula-family compilers provide controlled access to addresses, machine words, interrupts, device registers, and separately assembled routines. These facilities make the family useful for operating systems and instruments, but programs using them must declare the target machine and cease to be generally portable.</p>"},
      {id:"concurrency",title:"Processes and concurrency",html:"<p>Coroutines, processes, monitors, or device tasks vary by generation and implementation. Certified Latin engineering projects normally restrict concurrency to documented modules with bounded storage, declared priorities, and testable failure behavior.</p>"},
      {id:"latin",title:"Latin-bloc adoption",html:"<p>Latin universities teach Pascal first and introduce Modula in advanced systems, instrument, nuclear-control, and aerospace courses. Olivetti professional machines and joint technical programs value the language because interface discipline can bridge national hardware without erasing local operating systems.</p>"},
      {id:"commonwealth",title:"Commonwealth and international use",html:"<p>Commonwealth laboratories adopt Modula-family tools beside BCPL, C, Pascal, ML, and occam. American universities and workstation firms also experiment with them. Cross-bloc exchange is normally source-level and depends on declared character, numeric, module, and device profiles.</p>"},
      {id:"position",title:"Position in 1985",html:"<p>Modula is respected rather than universal. C has the larger portable systems market, Ada has military procurement, and Pascal retains the broad classroom base. Modula’s lasting advantage is the argument that interfaces, information hiding, and separately checked modules are part of the language rather than mere project convention.</p>"}
    ],
    related:[{href:"pascal-programming-language.html",kicker:"Predecessor",label:"Pascal"},{href:"algol-latin.html",kicker:"Latin scientific lineage",label:"ALGOL-Latin"},{href:"latin-programming-languages.html",kicker:"Regional adoption",label:"Latin-bloc Programming Languages"},{href:"c-programming-language.html",kicker:"Systems-language rival",label:"C"},{href:"ada-programming-language.html",kicker:"Procurement rival",label:"Ada"}],
    primarySources:[{href:"https://people.inf.ethz.ch/wirth/projects.html",label:"Niklaus Wirth — Modula project history"},{href:"https://people.inf.ethz.ch/wirth/Articles/Modula-Oberon-June.pdf",label:"Niklaus Wirth — The History of Modula-2 and Oberon"}],
    facts:[["Designer","Niklaus Wirth"],["Original project","1973–1976"],["Major revision","Modula-2, 1979"],["Principal unit","Module"],["Interface mechanism","Definition module"],["Compilation","Separate, type-checked"],["Primary fields","Systems, instruments, engineering"],["1985 status","Influential international specialist family"]]
  }),

  "kansu-42":institutionArticle({
    slug:"kansu-42",title:"Kansū 42",eyebrow:"Japanese functional research language · 42 generation",infoboxKicker:"Specialist functional language",
    lead:"<strong>Kansū 42</strong> (関数四二, <em>Kansū 42</em>) is a Japanese specialist functional-programming language introduced during the early 1980s. Influenced by Commonwealth <a href='ml-programming-language.html'>ML</a> and the American <a href='lambda-language.html'>Lambda</a> family, it provides a native-token, statically typed environment for functions, symbolic structures, compiler research, and experimental artificial intelligence. Kansū remains a university and corporate-laboratory language rather than a Japanese national production standard.<sup class='canon-note' data-provenance='a'>[a]</sup>",
    canon:"The name 関数四二; the reading Kansū 42; the early-1980s generation; ML and Lambda influences; native logical tokens; research use; and specialist status are established.<sup class='canon-note' data-provenance='a'>[a]</sup> The Common ML-style semantic subset described here is an incorporated provisional compatibility profile, not a complete independent Kansū language report. Exact introduction date, designers, institutions, grammar, module system, implementation shares, and standard library remain open.",
    sections:[
      {id:"research",title:"Research setting",html:"<p>International computing congresses during the 1970s and early 1980s exposed Japanese universities and corporate laboratories to Lisp, ML, Lambda, theorem provers, type systems, and functional compiler work. Imported papers, visiting researchers, translated teaching material, and cross-bloc character-standard meetings provided working examples.</p><p>Kansū was created to investigate those methods inside Japan's native source and runtime architecture. Its name uses the final two digits of the imperial year. 関数 means “function,” identifying the language's central research object rather than a ministry or manufacturer.</p>"},
      {id:"status",title:"Status of the specification",html:"<p>No complete Kansū language report has been established in the surviving common record. For interchange and archival description, Kansū 42 is treated as implementing a Common ML-style semantic subset with native tokens. This profile identifies the behavior expected by exchanged examples and research tools.</p><p>The profile does not settle exact syntax, keywords, library names, compiler organization, or later editions. Implementations may extend it if they declare the extension and preserve the common behavior used by portable programs.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"model",title:"Language model",html:"<p>A Kansū program evaluates expressions and applies functions to values. Lexical scope determines which binding a name denotes. Functions may receive functions, return functions, and capture bindings from their defining environment. Local types are inferred where the compiler has enough information.</p><p>The compatibility profile is statically typed. A program that applies a value in a way inconsistent with its inferred or declared type is rejected before execution. The compiler can retain general type variables where one definition safely operates on several types.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"data",title:"Values and algebraic data",html:"<p>The provisional profile includes integers, truth values, characters, strings, tuples, lists, function values, and user-declared algebraic data. A data declaration names a set of constructors and the values carried by each constructor. Recursive declarations support trees, symbolic expressions, syntax, and linked structures.</p><p>Values are immutable by default. A new value may share internal structure with an older one where the implementation can preserve observable behavior. Numeric ranges, string representation, and storage reclamation remain implementation properties.</p>"},
      {id:"patterns",title:"Patterns and definitions",html:"<p>Pattern matching decomposes tuples, lists, and algebraic values. A definition may provide several cases distinguished by constructors and nested patterns. Compilers diagnose incompatible patterns and may warn when cases are incomplete or unreachable.</p><p>Recursive declarations bind a function within its own definition. Mutually recursive groups allow several functions or data-processing stages to refer to one another. Exact syntax is not fixed by the compatibility profile.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"types",title:"Type inference",html:"<p>Local type inference reduces the number of declarations required in short research programs while retaining static checking. A compiler derives constraints from function application, constructors, operators, and patterns, then reports incompatible uses at the defining expression or call.</p><p>Interfaces to foreign code, files, instruments, and machine data require explicit types. Implementations publish the mapping between Kansū values and the numeric, character, record, and calling conventions of the host system.</p>"},
      {id:"effects",title:"Effects and external services",html:"<p>Immutable values and recursive functions form the ordinary program model. Input and output, mutable arrays, instruments, terminals, clocks, and foreign procedures enter through declared library interfaces. This separation lets a tool distinguish a mathematical transformation from an operation that changes external state.</p><p>The common profile does not impose one universal effect system. An implementation documents sequencing, error behavior, file lifetime, array mutation, and interruption for each external service.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"tokens",title:"Native tokens and display",html:"<p>Keywords, constructors, identifiers, type notation, strings, and comments can use Japanese logical tokens. Editors may render a common token in kana or an approved kanji form while preserving the stored identity. Horizontal and vertical presentations are both used in research environments.</p><p>Post-1980 systems exchange source through <a href='unicode-80.html'>UNICODE 80</a>. Character identity is distinct from font, glyph variant, and local byte encoding. Imported Latin mathematical notation may appear in mixed-script source without becoming a requirement of the native profile.</p>"},
      {id:"compilation",title:"Compilation",html:"<p>Kansū implementations may compile directly to a Japanese workstation's object format or produce a portable intermediate form. Interpreters are also used for teaching, testing, and rapid experimentation. Each release declares numeric representation, character profile, evaluation strategy, storage behavior, and foreign-function interface.</p><p>Functional calls, pattern selection, algebraic values, and automatic storage management impose different requirements from the arrays and procedures emphasized by KEISAN. Compiler construction is consequently both an implementation task and one of the language's principal research uses.</p>"},
      {id:"portability",title:"Program exchange",html:"<p>A portable Kansū package identifies the compatibility profile, character identity version, numeric assumptions, required libraries, foreign interfaces, and resource expectations. Source exchange is more common than binary exchange among unrelated Japanese workstations.</p><p>Examples translated from ML or Lambda include a correspondence note for types, evaluation, exceptions, character data, and external services. See <a href='software-portability.html'>software portability</a> for the distinction between semantic, source-profile, intermediate, and binary compatibility.</p>"},
      {id:"uses",title:"Uses",html:"<p>Kansū supports theorem tools, symbolic mathematics, compiler construction, type research, language processing, program transformation, and experimental artificial intelligence. Algebraic data and pattern matching are useful for syntax trees, formal terms, proof objects, and structured symbolic input.</p><p>The language appears in specialist university courses, corporate laboratories, and advanced software groups. It is not a normal environment for household programs, transaction processing, or certified factory controllers.</p>"},
      {id:"relations",title:"Relations with ML, Lambda, and Lisp",html:"<p>Kansū is influenced by Commonwealth ML's typed functional work and the American Lambda family's integration of symbolic programming with workstation research. Lisp supplies an older international tradition of functions, lists, symbolic expressions, and interactive language development.</p><p>Kansū is neither a direct translation of ML nor a national replacement for Lisp. Researchers adapt a shared functional vocabulary to Japanese text, institutional runtimes, and local compiler experiments, then publish correspondences for cross-bloc exchange.</p>"},
      {id:"production",title:"Relation to Japanese production languages",html:"<p><a href='keisan.html'>KEISAN</a> remains the principal scientific and engineering family. TEJUN handles administration, transactions, and controlled processes. Gakushū serves homes and schools. Kansū may supply compiler techniques, symbolic tools, or experimental components used around those systems.</p><p>A research prototype written in Kansū is normally translated, isolated behind an interface, or reimplemented before entering a tightly certified industrial installation. The language's specialist status is part of its established position.</p>"},
      {id:"position",title:"Position in 1985",html:"<p>By 1985 Kansū 42 remains a small research family. Its visible influence lies in type inference, compiler organization, symbolic software, and the participation of Japanese laboratories in international functional-language work.</p><p>Its exact institutional ownership, standard library, and successor editions remain unsettled. The common compatibility profile allows the archive and contemporary researchers to describe exchanged Kansū programs without claiming a mature national standard.</p>"}
    ],
    related:[{href:"japanese-programming-languages.html",kicker:"National software culture",label:"Japanese Programming Languages"},{href:"ml-programming-language.html",kicker:"Commonwealth influence",label:"ML"},{href:"lambda-language.html",kicker:"American influence",label:"Lambda"},{href:"lisp.html",kicker:"Symbolic ancestor",label:"Lisp"},{href:"ronri-44.html",kicker:"Logic research",label:"Ronri 44"},{href:"gazo-44.html",kicker:"Graphics research",label:"Gazō 44"},{href:"unicode-80.html",kicker:"Character identity",label:"UNICODE 80"},{href:"software-portability.html",kicker:"Exchange profiles",label:"Software Portability"}],
    facts:[["Japanese name","関数四二"],["Reading","Kansū 42"],["Generation","Early 1980s"],["Paradigm","Typed functional programming"],["Principal influences","ML and Lambda"],["Compatibility basis","Provisional Common ML-style subset"],["Typing","Static with local inference"],["Data model","Algebraic data and pattern matching"],["Source form","Native logical tokens"],["Primary use","Research and compiler work"],["1985 status","Specialist; not a national standard"]]
  }),

  "ronri-44":institutionArticle({
    slug:"ronri-44",title:"Ronri 44",eyebrow:"Japanese logic research language · 44 generation",infoboxKicker:"Specialist logic-programming language",
    lead:"<strong>Ronri 44</strong> (論理四四, <em>Ronri 44</em>) is Japan's specialist logic-programming language of the early 1980s. Developed from the <a href='marseille-prolog.html'>Marseille Prolog</a> tradition, it combines ordered clauses, unification, goal-directed search, native Japanese tokens, and multilingual UNICODE atoms. Ronri is used in university and corporate research, language analysis, planning, diagnosis, and experimental knowledge systems; it is not a national administrative language.<sup class='canon-note' data-provenance='a'>[a]</sup>",
    canon:"The name 論理四四; the reading Ronri 44; the early-1980s generation; Marseille Prolog influence; native and multilingual text; specialist research role; and nonreplacement of TEJUN, KEISAN, and Gakushū are established.<sup class='canon-note' data-provenance='a'>[a]</sup> Ordered practical Prolog search with UNICODE atoms is an incorporated provisional compatibility definition pending a complete Ronri report. Exact introduction year, designers, institutions, syntax, module rules, standard predicates, and implementation shares remain open.",
    sections:[
      {id:"origin",title:"From Marseille to Japan",html:"<p>Japanese investment in Marseille Prolog brought logic-programming researchers, interpreters, papers, and teaching material into Japanese universities and corporate laboratories. International conferences made unification and relational programming part of the common artificial-intelligence discussion.</p><p>Ronri developed as a native-token research environment. Its name uses the imperial-year suffix 四四 and the word 論理, “logic.” The language does not represent an independent Japanese invention of logic programming.<sup class='canon-note' data-provenance='a'>[a]</sup></p>"},
      {id:"status",title:"Status of the specification",html:"<p>No complete Ronri report has been established in the common record. The archive describes Ronri 44 through a practical Prolog compatibility profile supplemented by UNICODE atoms and Japanese source conventions.</p><p>This profile fixes enough behavior to discuss exchanged programs: ordered clauses, goal reduction, unification, depth-first backtracking, and implementation-declared resource limits. Exact syntax, predefined predicates, modules, indexing, and foreign interfaces may differ.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"terms",title:"Terms and clauses",html:"<p>Programs contain facts and rules expressed as ordered clauses. Terms include atoms, numbers, variables, and compound structures. Lists provide a common recursive representation for text fragments, sequences, trees, and symbolic data.</p><p>A predicate is identified by its name and arity. Several clauses with the same predicate and arity are considered in source order unless an implementation documents an equivalent compiled arrangement.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"queries",title:"Queries and goals",html:"<p>A query creates one or more goals. The engine selects a goal, searches for a matching clause, and attempts to satisfy the clause's body. Successful variable bindings form an answer. On request or failure, the engine may return to an earlier choice point and search another alternative.</p><p>Answers can contain unresolved variables or structured terms. Programs that require a single operational result must declare how additional solutions, failure, and resource exhaustion are handled.</p>"},
      {id:"unification",title:"Unification",html:"<p>Unification attempts to make two terms identical by binding variables consistently. It descends through compound structures and rejects incompatible atoms, numbers, or constructors. Bindings made during an unsuccessful alternative are undone during backtracking.</p><p>Practical engines may omit the occurs-check, as many Prolog systems do. An implementation must disclose that choice because it permits cyclic bindings or behavior that differs from complete first-order unification.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"search",title:"Search and control",html:"<p>The compatibility profile uses ordered, depth-first search. Clause order and goal order affect termination, resource use, and which answer appears first. Cuts or comparable commitment operations can discard choice points. Indexing can change speed while preserving declared answer behavior.</p><p>Heap limits, stack limits, depth bounds, interruption policy, and timeouts are part of an implementation profile. A logically satisfiable query may still fail operationally when the selected search path exhausts available resources.</p>"},
      {id:"text",title:"Native and multilingual atoms",html:"<p>Predicate names, constants, quoted atoms, strings, and comments can preserve Japanese and other <a href='unicode-80.html'>UNICODE 80</a> character identities. Display form, font, vertical orientation, and collation remain separate from logical identity.</p><p>Native tokens can be rendered in Japanese while foreign names and data remain in their registered scripts. Modules and interfaces identify predicates by name and arity together with the relevant character profile. Binary equality compares identity rather than visual glyph similarity.</p>"},
      {id:"data",title:"Files and institutional data",html:"<p>Files, databases, instruments, and administrative systems enter through external predicates. An interface declares conversions between Ronri terms and local records, numeric fields, character identities, failures, and transaction boundaries.</p><p>A database query performed by the inference engine does not by itself authorize a change to the database. Update, confirmation, rollback, and operator authority remain the responsibility of the external service or a connected TEJUN procedure.</p>"},
      {id:"implementation",title:"Implementation families",html:"<p>Interpreters run on Japanese workstations and larger institutional systems. Selected compilers lower stable predicates into indexed or machine-specific internal forms. Development environments display goals, variable bindings, choice points, and resource use for teaching and diagnosis.</p><p>Each implementation records its engine version, character profile, arithmetic, clause indexing, cut behavior, occurs-check policy, memory limits, external predicates, and interruption rules. Binary compatibility among unrelated workstations is not assumed.</p>"},
      {id:"uses",title:"Language and knowledge research",html:"<p>Laboratories apply Ronri to language analysis, translation, grammar experiments, theorem work, planning, diagnosis, law, maintenance rules, customs classification, and technical knowledge bases. Multilingual atoms make it useful where rules and terms cross Japanese and associated-state scripts.</p><p>Research systems may explain an answer by recording the clauses and bindings used. The quality of an explanation depends on the program and engine; it is not an automatic property of every Ronri query.</p>"},
      {id:"governance",title:"Administrative experiments",html:"<p>Customs, maintenance, legal, and diagnostic experiments place declarative rules close to institutional terminology. Sensitive deployments record the rule base, engine version, search limits, external data sources, and the office or person responsible for approval.</p><p>Production transactions normally remain in <a href='tejun.html'>TEJUN</a>. Ronri may classify, propose, or diagnose, after which a declared procedure validates the result and performs any authorized action.</p>"},
      {id:"limits",title:"Operational and institutional limits",html:"<p>A compact rule base can conceal incomplete facts, disputed classifications, exceptions, or policy choices. Clause order and cuts may affect the result even when the rules read declaratively. Nontermination and memory exhaustion remain practical hazards.</p><p>Commercial and government users therefore require test queries, documented data provenance, resource bounds, and operator review appropriate to the application. These controls describe deployment practice rather than a guarantee supplied by the language.</p>"},
      {id:"relations",title:"Relations with other languages",html:"<p>Marseille Prolog is Ronri's direct intellectual and practical ancestor. Kansū 42 explores typed functional programming, while Gazō 44 addresses retained graphics and interfaces. The three share Japanese character and workstation infrastructure but do not form one language.</p><p>KEISAN remains the scientific family, TEJUN the administrative and process family, and Gakushū the home and educational family. Ronri does not replace any of them.</p>"},
      {id:"position",title:"Position in 1985",html:"<p>Ronri attracts attention in the international artificial-intelligence community and in Japanese language and knowledge-system research. Its multilingual atoms and connection to Marseille make it an important cross-bloc experimental language.</p><p>By 1985 it remains a specialist family. The common compatibility profile permits source exchange and comparison, while exact institutional ownership, implementation shares, and a complete independent standard remain unsettled.</p>"}
    ],
    related:[{href:"japanese-programming-languages.html",kicker:"National software culture",label:"Japanese Programming Languages"},{href:"marseille-prolog.html",kicker:"Direct ancestor",label:"Marseille Prolog"},{href:"kansu-42.html",kicker:"Functional research",label:"Kansū 42"},{href:"gazo-44.html",kicker:"Graphics research",label:"Gazō 44"},{href:"tejun.html",kicker:"Production procedure family",label:"TEJUN"},{href:"unicode-80.html",kicker:"Multilingual atoms",label:"UNICODE 80"},{href:"software-portability.html",kicker:"Exchange profiles",label:"Software Portability"}],
    facts:[["Japanese name","論理四四"],["Reading","Ronri 44"],["Generation","Early 1980s"],["Paradigm","Logic programming"],["Principal influence","Marseille Prolog"],["Compatibility basis","Provisional practical Prolog profile"],["Search model","Ordered depth-first backtracking"],["Core operation","Unification"],["Text model","UNICODE 80 atoms"],["Primary use","Research and knowledge systems"],["1985 status","Specialist; not a national standard"]]
  }),

  "gazo-44":institutionArticle({
    slug:"gazo-44",title:"Gazō 44",eyebrow:"Japanese graphics research language · 44 generation",infoboxKicker:"Specialist graphics and interface language",
    lead:"<strong>Gazō 44</strong> (画像四四, <em>Gazō 44</em>) is a Japanese specialist language for interactive graphics, animation, sprite systems, and interface research. Developed during the early 1980s, it describes retained scene objects and event procedures above the graphical hardware used by Japanese workstations, game systems, laboratories, and design tools. Gazō supplies a shared experimental vocabulary across otherwise incompatible devices without becoming the ordinary language of commercial cartridges or business applications.<sup class='canon-note' data-provenance='a'>[a]</sup>",
    canon:"The name 画像四四; the reading Gazō 44; the early-1980s generation; graphics, animation, and interface purpose; retained-object and event-procedure model; relationship to Japanese graphics and sprite hardware; comparison with German Bildschrift; and specialist status are established.<sup class='canon-note' data-provenance='a'>[a]</sup> The technical model described here is an incorporated provisional compatibility profile rather than a complete Gazō standard. Exact introduction year, designers, institutions, syntax, object system, event ordering, rendering rules, and implementation shares remain open.",
    sections:[
      {id:"setting",title:"Japanese graphics research",html:"<p>Cheaper semiconductor memory, consumer game hardware, broadcast graphics, design workstations, scientific displays, and native-character terminals expanded Japanese graphics work during the late 1970s and early 1980s. Most equipment still exposed different display lists, sprite registers, palettes, text generators, and input devices.</p><p>Gazō placed a structured object-and-event environment above those devices. Its title uses the imperial-year suffix 四四 and the word 画像, “image.” It remained a research language associated with universities, corporate laboratories, and high-end tool groups.</p>"},
      {id:"status",title:"Status of the specification",html:"<p>No complete Gazō language report has been established in the common record. The archive uses a retained-scene and event-procedure compatibility profile comparable in broad purpose to German Bildschrift while retaining Japanese text, sprite, and device conventions.</p><p>The profile does not fix exact syntax, object inheritance, timing, rendering order, or a standard widget library. Implementations declare their capabilities and any vendor extensions.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"scene",title:"Retained scene objects",html:"<p>A program creates named visual objects with geometry, image, text, transform, layer, visibility, and parent relationships. The runtime retains the scene between operations. Changing one property marks the corresponding object or region for redisplay.</p><p>This model differs from immediate drawing code that reconstructs an entire frame from commands. An implementation may still use immediate hardware internally, provided the declared retained-object behavior remains available to the program.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"hierarchy",title:"Hierarchy and transformation",html:"<p>Objects may be grouped beneath a parent. Position, scale, orientation, visibility, and clipping can be inherited or combined through the hierarchy. Moving a group moves its children according to the declared transform.</p><p>Layers establish front-to-back relationships for maps, diagrams, windows, labels, and sprite scenes. Exact overlap, clipping, and redraw behavior belongs to the machine profile where the provisional common model does not specify it.</p>"},
      {id:"resources",title:"Images and reusable resources",html:"<p>Image, tile, font, palette, and animation resources are named separately from the objects that display them. A resource record identifies its character or image format, dimensions, color assumptions, and permitted transformations. Several objects may refer to one resource.</p><p>Portable packages may include alternative resources for machines with different resolutions or color capacities. A loader selects the closest declared profile or reports that the required capability is unavailable.</p>"},
      {id:"events",title:"Event procedures",html:"<p>Keyboard, pointer, controller, timer, collision, message, and device events invoke procedures attached to views or objects. An event carries a type, target, relevant values, and implementation-declared timing information.</p><p>The runtime manages dispatch rather than requiring every application to poll every input register. Ordering among simultaneous events, re-entry, queue bounds, and interruption behavior remain part of the implementation profile.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"animation",title:"Animation and sprites",html:"<p>Animation changes object properties or selects frames from a named resource over time. Sprite-oriented profiles expose position, image frame, palette, collision class, visibility, and layer through retained objects. Tiled backgrounds can be represented by maps and reusable tile resources.</p><p>The profile does not promise identical timing or color on every machine. Commercial or experimental tools state the required frame rate, sprite capacity, palette behavior, collision rules, and fallback policy.</p>"},
      {id:"hardware",title:"Hardware profiles",html:"<p>Profiles expose hardware sprites, tiled backgrounds, palettes, vector or bitmap acceleration, frame buffers, printers, plotters, and vertical-text services through declared capabilities. A portable object may fall back to software drawing when the profile permits it.</p><p>Exact memory layout, register access, timing, and color encoding remain machine-specific. Low-level procedures can be attached through an external interface, but packages that use them cease to be portable beyond the named target.</p>"},
      {id:"text",title:"Text and layout",html:"<p>Gazō uses <a href='unicode-80.html'>UNICODE 80</a> character identity. Font, glyph, vertical orientation, ruby, punctuation placement, line direction, and spacing are presentation properties distinct from the text stored by the program.</p><p>The same textual resource can be laid out vertically or horizontally when its profile supplies the necessary fonts and rules. Japanese, Latin, and other registered scripts may coexist in labels, diagrams, controls, and imported data.</p>"},
      {id:"interfaces",title:"Interface construction",html:"<p>Views, labels, fields, selections, diagrams, and controls can be assembled from retained objects and connected to event procedures. Research environments use the model to compare interaction patterns without binding every application directly to one workstation's device routines.</p><p>A complete standard widget set has not been established. Laboratories and manufacturers therefore publish libraries with their own object names, appearance, keyboard conventions, and external-service bindings.</p>"},
      {id:"implementation",title:"Implementation",html:"<p>Gazō systems may interpret scene descriptions, compile event procedures, or translate a restricted package into a vendor graphics engine. Runtimes maintain the object graph, dispatch events, map logical resources to devices, and manage redisplay.</p><p>An implementation identifies its language profile, character version, scene limits, event queue, coordinate and numeric model, supported resources, hardware capabilities, and external interfaces. Binary packages are not assumed to move between unrelated machines.</p>"},
      {id:"uses",title:"Scientific and industrial uses",html:"<p>Research systems use Gazō for map displays, scientific visualization, educational diagrams, industrial panels, simulation displays, broadcast titling, and experimental graphical desktops. Instrument and process data enter through declared external services.</p><p>Operational industrial control remains in TEJUN or equipment-specific software. Gazō supplies the display and interaction layer where a project adopts it; authorization and safe-state behavior remain outside the provisional graphics model.</p>"},
      {id:"games",title:"Games and media tools",html:"<p>Gazō is used for sprite experiments, scene editors, animation tools, level and map construction, and interface prototypes. Its object vocabulary maps naturally to Japanese game hardware, but ordinary commercial cartridges commonly use assembly, compact systems tools, or vendor engines.</p><p>Restricted Gazō subsets may be translated into those engines during production. The language therefore influences tools and research more than the final source found in the broader <a href='video-games-japan.html'>Japanese video-game industry</a>.</p>"},
      {id:"exchange",title:"Program and resource exchange",html:"<p>A portable Gazō package records the language profile, UNICODE version, coordinate assumptions, resource formats, event requirements, and device capabilities. Alternative resources and fallback procedures allow one package to target several related machines.</p><p>Source and resource exchange are more common than binary portability. Conversion tools can preserve object structure and character identity while replacing fonts, palettes, input mappings, or vendor procedures.</p>"},
      {id:"comparison",title:"Relationship to foreign systems",html:"<p>Gazō is compared with <a href='bildschrift.html'>German Bildschrift</a>, American <a href='smalltalk.html'>Smalltalk</a> environments, Civic and Meridian resource systems, and Commonwealth graphical toolkits. Retained objects, events, and reusable resources belong to a wider international graphics discussion.</p><p>Gazō is distinguished by Japanese logical tokens, vertical text, UNICODE 80 identity, sprite-oriented profiles, and adaptation to domestic devices. Comparison does not imply source or binary compatibility.</p>"},
      {id:"relations",title:"Relation to Japanese languages",html:"<p>Kansū 42 addresses typed functional research and Ronri 44 logic programming. Gazō can call or display results produced by research tools in those languages through declared interfaces, but the three do not share one execution model.</p><p>Gakushū provides accessible household graphics and sound, KEISAN supports scientific plotting and visualization, and TEJUN supplies process and device control. Gazō concentrates on retained interactive scenes and interface experimentation.</p>"},
      {id:"position",title:"Position in 1985",html:"<p>By 1985 Gazō 44 is influential in laboratories, workstation groups, graphics-tool research, and selected design environments. It gives researchers a common vocabulary for scenes, resources, events, sprites, and multilingual layout across incompatible Japanese hardware.</p><p>It is not a national standard or the ordinary language of game cartridges and business applications. Exact syntax, libraries, implementation shares, and successor revisions remain open beyond the provisional compatibility profile.</p>"}
    ],
    related:[{href:"japanese-programming-languages.html",kicker:"National software culture",label:"Japanese Programming Languages"},{href:"kansu-42.html",kicker:"Functional research",label:"Kansū 42"},{href:"ronri-44.html",kicker:"Logic research",label:"Ronri 44"},{href:"smalltalk.html",kicker:"Graphical comparison",label:"Smalltalk"},{href:"civic-programming-language.html",kicker:"American graphical system",label:"Civic"},{href:"bildschrift.html",kicker:"German comparison",label:"Bildschrift"},{href:"unicode-80.html",kicker:"Text identity",label:"UNICODE 80"},{href:"video-games-japan.html",kicker:"Hardware and tools",label:"Video Games in Japan"}],
    facts:[["Japanese name","画像四四"],["Reading","Gazō 44"],["Generation","Early 1980s"],["Paradigm","Retained graphics and events"],["Compatibility basis","Provisional scene-object profile"],["Principal unit","Retained scene object"],["Interaction","Event procedures"],["Primary targets","Workstations and sprite hardware"],["Text model","UNICODE 80 layout profiles"],["Comparable German system","Bildschrift"],["1985 status","Specialist; not a national standard"]]
  }),

  "international-character-data-standards-council":institutionArticle({
    slug:"international-character-data-standards-council",title:"International Character and Data Standards Council",eyebrow:"Cross-bloc standards body · 1977–1985",infoboxKicker:"International technical institution",
    lead:"The International Character and Data Standards Council (ICDSC) is the cross-bloc technical body that negotiates common character identity without imposing a common computer system. Its first great settlement is UNICODE 80, the 16-bit abstract character standard adopted at the Tokyo–Melbourne congress of 1980.",
    canon:"The council’s late-1970s formation, Kyoto and Geneva work, Tokyo–Melbourne congress, UNICODE 80 publication, and uneven national adoption are established. Its permanent seat, complete membership, budget, and later organizational history remain open.",
    sections:[
      {id:"need",title:"The character crisis",html:"<p>By the 1970s, Japanese multibyte registries, Commonwealth and American codes, Latin accented repertoires, German standards, and dozens of regional scripts make international records expensive and error-prone. A character can survive visually while losing identity, order, or reversibility during conversion.</p>"},
      {id:"kyoto",title:"Kyoto draft, 1977",html:"<p>The Kyoto work begins from the claim that every supported character needs a stable abstract identity distinct from its local storage code, font, keyboard, or vertical orientation. Delegates disagree over repertoire, ordering, Han characters, and the cost imposed on existing machines.</p>"},
      {id:"geneva",title:"Geneva compromise, 1978–1979",html:"<p>Geneva negotiations separate the universal identity layer from compact local encodings. Systems may continue to store efficient national forms if their gateways can map them reversibly to the common 16-bit exchange identity.</p>"},
      {id:"congress",title:"Tokyo–Melbourne congress, 1980",html:"<p>The paired congress adopts the first edition under the all-capitals brand <a href='unicode-80.html'>UNICODE 80</a>. UNICODE is a name rather than an acronym. The council publishes character identities, ordering rules, conversion requirements, and registries rather than an operating system or network protocol.</p>"},
      {id:"scope",title:"What the council standardizes",html:"<p>The ICDSC coordinates character and selected data interchange standards. It does not certify political terminology, fonts, keyboards, programming languages, database design, or the right of any bloc to control a user’s machine.</p>"},
      {id:"han",title:"Script settlements",html:"<p>The first edition includes traditional Chinese characters rather than a later simplified-Chinese repertoire, alongside Japanese, Korean, Latin, Greek, Cyrillic, and the major scripts needed by participating systems. Rendering properties remain distinct from abstract identity.</p>"},
      {id:"adoption",title:"Uneven adoption",html:"<p>Japan and the Latin bloc apply the standard most strictly; the Commonwealth uses it opportunistically; Germany delays broad acceptance; and decentralized American vendors adopt it last. Gateways and Bridge environments create practical convergence during the 1990s.</p>"},
      {id:"legacy",title:"Institutional legacy",html:"<p>The council succeeds because it standardizes the point of exchange rather than demanding one universal computer culture. Its work later makes Weltnetz multilingual traffic, international software catalogs, and cross-bloc records possible without dissolving national platforms.</p>"}
    ],
    related:[{href:"unicode-80.html",kicker:"First great standard",label:"UNICODE 80"},{href:"computing-networks.html",kicker:"International network layer",label:"Computing and Global Networks"},{href:"software-portability.html",kicker:"Interchange problem",label:"Cross-Bloc Software Portability"},{href:"bridge-operating-environment.html",kicker:"Compatibility environment",label:"Bridge"},{href:"japanese-programming-languages.html",kicker:"Early strict adopter",label:"Japanese Programming Languages"}],
    facts:[["Abbreviation","ICDSC"],["Formation","Late 1970s"],["First draft conference","Kyoto, 1977"],["Compromise negotiations","Geneva, 1978–1979"],["Adoption congress","Tokyo–Melbourne, 1980"],["First major publication","UNICODE 80"],["Identity width","16-bit"],["Permanent headquarters","Not yet established in canon"]],
    categories:["Computing","Standards organizations","UNICODE 80","International institutions"]
  }),

  "concord-architecture":institutionArticle({
    slug:"concord-architecture",title:"Concord architecture",eyebrow:"American personal-computing platform · 1978–1985",infoboxKicker:"Closed integrated computer architecture",
    lead:"The Concord architecture is Elias Rowan Mercer’s closed American personal-computing platform. Concord One and the graphical Concord Meridian join designed hardware, the Civic language, proprietary objects, authorized development systems, and controlled publication into the polished ecosystem critics call the ‘gated republic.’",
    canon:"The platform’s founder, 1978 and 1983 systems, Civic generations, graphical services, object signing, controlled publishing, political associations, and rivalry with Bridge are established. Exact processors and peripheral catalogs remain open.",
    sections:[
      {id:"founding",title:"Mercer and the coherent machine",html:"<p><a href='elias-mercer.html'>Elias Mercer</a> founds Concord Computer Works in Silicon Valley around the belief that a personal computer should arrive as a designed public environment rather than an unfinished kit. Hardware, software, typography, documentation, and approved publishing are treated as one civic object.</p>"},
      {id:"one",title:"Concord One, 1978",html:"<p>The Concord One is the mass-market foundation of the platform. Its integrated operating services, storage formats, peripherals, and <a href='civic-programming-language.html'>Civic 78</a> tools give households, schools, offices, and publishers a stable target while limiting arbitrary native access.</p>"},
      {id:"objects",title:"Objects, signatures, and serialization",html:"<p>Applications compile into proprietary Concord objects carrying interface versions, machine requirements, and publisher signatures. Serialized systems and controlled loaders protect compatibility and commercial identity but make lawful independent distribution dependent on company approval.</p>"},
      {id:"development",title:"Authorized development",html:"<p>Full compilers, signing tools, privileged interfaces, and internal documentation are concentrated on authorized development machines. Ordinary users can program within the public environment, but system software and commercial publication require contractual access.</p>"},
      {id:"meridian",title:"Concord Meridian, 1983",html:"<p>Meridian adds a graphical desktop built around windows, icons, pointing, typography, networking, and sound. Civic 83 supplies classes, managed references, resource declarations, events, and exceptions so applications participate in the shared visual and interaction model.</p>"},
      {id:"politics",title:"The gated republic",html:"<p>Mercer connects bounded technical authority to National Renewal ideas about ordered civic participation. Supporters praise coherent standards, safe distribution, and public legibility; critics argue that a private company controls who may publish, repair, emulate, and define legitimate use.</p>"},
      {id:"bridge",title:"Concord and Bridge",html:"<p><a href='bridge-operating-environment.html'>Bridge</a> promises portable applications across licensed competing machines; Concord promises greater depth inside one integrated system. IBM’s 1981 Bridge/16 adoption gives Bridge the larger compatible market, but Concord retains prestige in design, publishing, education, and selected institutions.</p>"},
      {id:"position",title:"Position in 1985 and after",html:"<p>Employee protests and urban boycotts follow Mercer’s 1984 Phillips–Landry endorsement, yet the platform does not collapse. Concord remains a durable closed ecosystem even as Weltnetz and Bridge become common layers: connected to the wider world, but governed through its own gates.</p>"}
    ],
    related:[{href:"elias-mercer.html",kicker:"Founder",label:"Elias Rowan Mercer"},{href:"civic-programming-language.html",kicker:"Application language",label:"Civic"},{href:"bridge-operating-environment.html",kicker:"Compatible rival",label:"Bridge"},{href:"platform-society.html",kicker:"Consumer setting",label:"Consumer Computing and Platform Society"},{href:"software-portability.html",kicker:"Interchange problem",label:"Cross-Bloc Software Portability"}],
    facts:[["Company","Concord Computer Works"],["Founder","Elias Rowan Mercer"],["First system","Concord One, 1978"],["Graphical system","Concord Meridian, 1983"],["Application language","Civic"],["Distribution","Signed proprietary objects"],["Development","Authorized machines and publishers"],["Common description","The gated republic"]],
    categories:["Computing","Personal computing","Concord","Platforms","United States"]
  }),

  "shadownet":institutionArticle({
    slug:"shadownet",title:"ShadowNet",eyebrow:"American network culture · c. 1995–2005",infoboxKicker:"Pseudonymous Weltnetz overlay",
    lead:"ShadowNet is the American pseudonymous cultural and application overlay that develops on Weltnetz in the late 1990s. It is not a separate physical network or a single hidden service: ‘going shadow’ means using relays, unlisted communities, signed handles, and compartmented identities instead of the public employment-safe identity of Brightnet.",
    canon:"Its relationship to Weltnetz, late-1990s growth, Brightnet contrast, signed pseudonymity, commercial services, political role, and foreign variants are established through about 2005. Individual platforms, firms, scandals, and laws remain open.",
    sections:[
      {id:"not-network",title:"Not a second network",html:"<p>ShadowNet traffic crosses the same cables, packet systems, satellites, gateways, and service carriers as ordinary <a href='computing-networks.html'>Weltnetz</a> traffic. The distinction lies in applications, routing practice, discoverability, identity, and community norms—not in a physically separate American internet or a single universal dark web.</p>"},
      {id:"origins",title:"Privacy relays, 1995–1998",html:"<p>Early <a href='privacy-router-industry.html'>privacy-router and relay firms</a> serve political groups, hobbyists, journalists, game communities, dismissed workers, and users avoiding sponsor or employer scrutiny. ‘ShadowNet’ begins largely as an accusation implying evasion, disloyalty, or concealed vice.</p>"},
      {id:"handles",title:"Signed handles, 1998–2000",html:"<p>Cheap hosting, stable <a href='signed-handles.html'>cryptographic handles</a>, invitation systems, and portable reputation let pseudonymous people make contracts, moderate communities, publish work, and maintain trust without revealing their Brightnet identity to every participant.</p>"},
      {id:"brightnet",title:"Brightnet and going shadow",html:"<p><a href='brightnet.html'>Brightnet</a> is the public, legal, employment-safe identity layer used for official records, professional credentials, retail accounts, and respectable social presence. A person may move between bright and shadow roles, but exposure that links them can destroy employment, sponsorship, or political standing.</p>"},
      {id:"ordinary",title:"Normalization by 2003–2005",html:"<p>By the mid-2000s, ‘going shadow’ is often neutral or positive. Gaming, modding, independent art, sensitive political discussion, dissident history campaigns, sexual minorities, and ordinary subcultures use pseudonymity as protection from institutions rather than evidence of criminal purpose.</p>"},
      {id:"corporations",title:"Corporate appropriation",html:"<p>Corporations do not stand outside ShadowNet. They sell privacy routing, hosting, reputation, advertising, moderation, and access. They also monitor communities, maintain <a href='corporate-political-blacklists.html'>political blacklists</a>, and quietly sponsor useful anonymous campaigns. Competition between firms prevents any one company from suppressing the overlay completely.</p>"},
      {id:"privacy-market",title:"Privacy services and reputation capital",html:"<!-- altwwii-writer-block:start id=wb-r-20260816-s5v9k writer=r kind=analysis created=2026-08-16T14:02:00-06:00 --><p>ShadowNet privacy was produced through paid and unpaid services rather than supplied by the name of the network. Access lines, relay subscriptions, hosting, storage, software, addresses, directories, moderation, key management, payment intermediaries, and user labour separated parts of an identity. A low money price could be accompanied by delay, difficult discovery, unreliable service, exposure risk, fraud, and the time required to establish trust.</p><div class='table-wrap'><table class='wiki-table'><thead><tr><th>Service or asset</th><th>Price or return</th><th>Cost and entry test</th></tr></thead><tbody><tr><td>Privacy routing and access</td><td>Subscription, equipment, connection time, latency, and reduced linkability</td><td>Whether users could compare logs, route separation, failures, exposure history, and competing relays</td></tr><tr><td>Unlisted hosting and directories</td><td>Hosting charge, bandwidth, availability, discovery, and protection from ordinary indexing</td><td>Whether hosts or directories could exclude rivals, sell traffic knowledge, or impose hidden sponsorship</td></tr><tr><td>Signed handle and reputation</td><td>Accumulated work, recommendations, transaction history, moderation, and audience</td><td>Key control, portability, impersonation, doxing, community exit, and transfer to another service</td></tr><tr><td>Escrow, payment, and moderation</td><td>Fee for enforcement, fraud screening, dispute handling, and community order</td><td>Loss reserves, appeals, conflicts of interest, false accusation, and competition among intermediaries</td></tr><tr><td>Corporate research and influence</td><td>Consumer information, talent, political intelligence, advertising, leaks, and campaigns</td><td>Disclosure of sponsorship, data retention, blacklist use, manipulation, and who bears harm from surveillance</td></tr></tbody></table></div><p>Pseudonymous reputation was capital created through repeated dealings. It reduced the information problem that complete anonymity imposed, allowing a programmer, merchant, moderator, journalist, or community member to make credible promises without disclosing a civil identity. That capital could be destroyed by key compromise, doxing, false attribution, a host's closure, or exclusion from a directory. Portability of keys, archives, recommendations, and address lists determined whether the reputation belonged chiefly to the user or to the service.</p><p>Decentralized entry limited the ability of one corporation to close the overlay, but it did not eliminate concentrated chokepoints. Access providers observed connections, major directories controlled discovery, popular hosts accumulated audiences, payment firms saw transactions, and employers or insurers could act upon exposed identities. A privacy company could earn from genuine user demand while also selling data, accepting corporate sponsorship, steering users into monitored spaces, or relying upon political retaliation that made privacy necessary.</p><p>Unlisted services also displaced enforcement costs. Fraud, piracy, extortion, malware, false claims, and contract breach could be borne by victims, volunteer moderators, hosts, intermediaries, or the wider carriage network. Escrow, reputation, insurance, community rules, and competing investigation supplied partial governance. Civil identification remained valuable where coercive enforcement or recovery of a large loss was required.</p><p>Exact access and hosting prices, relay topology, bandwidth, firms, market shares, logging practices, sponsorship, advertising, payment methods, fraud and insurance losses, reputation portability, blacklist exchanges, public subsidies, and enforcement law remain open.</p><!-- altwwii-writer-block:end -->"},
      {id:"abuse",title:"Doxing, laundering, and imperfect erasure",html:"<p><a href='doxing.html'>Doxing</a> links a handle to legal identity. Credential laundering rebuilds reputation after exposure. <a href='identity-cleaning-industry.html'>Identity-cleaning firms</a> negotiate removals or corporate rehabilitation, but cannot erase widely copied distributed records. Permanent exposure remains a central fear of network life.</p>"},
      {id:"foreign",title:"Foreign variants and political effect",html:"<p><a href='foreign-shadownet-ecosystems.html'>Germany’s narrower Schattennetz</a> operates under stronger identification and surveillance. Japan occupies a middle position. Britain and the Latin bloc develop their own legal and cultural variants. Pseudonymity becomes a political pressure valve and a market for surveillance, manipulation, and selective enforcement in every system.</p>"}
    ],
    related:[{href:"computing-networks.html",kicker:"Physical and protocol layer",label:"Computing and Global Networks"},{href:"platform-society.html",kicker:"Consumer setting",label:"Consumer Computing and Platform Society"},{href:"five-party-republic.html",kicker:"American political setting",label:"Five-Party Republic"},{href:"software-portability.html",kicker:"Shared technical layer",label:"Cross-Bloc Software Portability"},{href:"concord-architecture.html",kicker:"Closed connected ecosystem",label:"Concord Architecture"}],
    facts:[["Emergence","c. 1995–1998"],["Normalization","c. 2003–2005"],["Physical network","Weltnetz"],["Public counterpart","Brightnet"],["Characteristic identity","Stable signed pseudonym"],["Characteristic services","Relays, unlisted hosting, reputation"],["German counterpart","Schattennetz"],["Separate physical network","No"]],
    categories:["Computing","Weltnetz","Network culture","United States","Pseudonymity"]
  })
});

const appendRelated = (slug,item) => {
  const related = window.deepArticles[slug]?.related;
  if (related && !related.some(entry=>entry.href===item.href)) related.unshift(item);
};

